{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "HealthAndBeautyBusiness",
      "@id": "https://example.com/#organization",
      "name": "ສະຕູດິໂອບອດີແຄຕົວຢ່າງ",
      "description": "ບອດີແຄ ແລະ ການຜ່ອນຄາຍດ້ວຍມືສຳລັບຄໍ, ບ່າ ແລະ ຫຼັງ. ພວກເຮົາບໍ່ແມ່ນຜູ້ໃຫ້ບໍລິການທາງການແພດ: ພວກເຮົາບໍ່ໄດ້ວິນິດໄສ ຫຼື ປິ່ນປົວພະຍາດ ແລະ ໃຊ້ປະກັນສຸຂະພາບບໍ່ໄດ້.",
      "address": { "@type": "PostalAddress", "streetAddress": "1-2-3 Example St, 2nd floor, Example City" },
      "telephone": "+1-000-000-0000",
      "url": "https://example.com/",
      "openingHours": "Mo-Sa 10:00-21:00"
    },
    {
      "@type": "Service",
      "@id": "https://example.com/#nurevo-service-1",
      "name": "ບອດີແຄທົ່ວຮ່າງກາຍ, 60 ນາທີ",
      "description": "ໃສ່ເຄື່ອງຢູ່ຕະຫຼອດ, ໃຊ້ມືທົ່ວຮ່າງກາຍ. ປັບນ້ຳໜັກມືໄດ້ໃນລະຫວ່າງເຊດຊັນ. ຖ້າທ່ານຖືພາ ຫຼື ກຳລັງປິ່ນປົວພະຍາດ ກະລຸນາປຶກສາແພດກ່ອນຈອງ.",
      "category": "ບອດີແຄ",
      "provider": { "@id": "https://example.com/#organization" },
      "offers": { "@type": "Offer", "price": "45", "priceCurrency": "USD" },
      "potentialAction": {
        "@type": "ReserveAction",
        "target": { "@type": "EntryPoint", "urlTemplate": "https://example.com/book" },
        "result": { "@type": "Reservation", "name": "ບອດີແຄທົ່ວຮ່າງກາຍ, 60 ນາທີ" }
      }
    }
  ]
}
